package com.gauntletrecorder;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a developer-mode RuneLite client with this plugin sideloaded.
 * Run it with `./gradlew run`.
 */
public class GauntletRecorderTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GauntletRecorderPlugin.class);
		RuneLite.main(args);
	}
}

package com.gauntletrecorder;

import net.runelite.api.ChatMessageType;
import net.runelite.api.MenuAction;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GauntletRecorderPluginTest
{
	@Test
	public void recordsOnlyNonPlayerSystemMessages()
	{
		assertTrue(GauntletRecorderPlugin.isRecordedMessageType(ChatMessageType.GAMEMESSAGE));
		assertTrue(GauntletRecorderPlugin.isRecordedMessageType(ChatMessageType.SPAM));
		assertFalse(GauntletRecorderPlugin.isRecordedMessageType(ChatMessageType.PUBLICCHAT));
		assertFalse(GauntletRecorderPlugin.isRecordedMessageType(ChatMessageType.PRIVATECHAT));
	}

	@Test
	@SuppressWarnings("deprecation")
	public void recordsGameObjectActionsOnly()
	{
		assertTrue(GauntletRecorderPlugin.isGameObjectAction(MenuAction.GAME_OBJECT_FIRST_OPTION));
		assertTrue(GauntletRecorderPlugin.isGameObjectAction(MenuAction.GAME_OBJECT_FIFTH_OPTION));
		assertTrue(GauntletRecorderPlugin.isGameObjectAction(MenuAction.ITEM_USE_ON_GAME_OBJECT));
		assertTrue(GauntletRecorderPlugin.isGameObjectAction(MenuAction.WIDGET_TARGET_ON_GAME_OBJECT));
		assertFalse(GauntletRecorderPlugin.isGameObjectAction(MenuAction.NPC_FIRST_OPTION));
		assertFalse(GauntletRecorderPlugin.isGameObjectAction(MenuAction.WALK));
		assertFalse(GauntletRecorderPlugin.isGameObjectAction(null));
	}

	@Test
	public void makesTextSafeForOneTabDelimitedLine()
	{
		assertEquals("", GauntletRecorderPlugin.safeField(null));
		assertEquals("Light Node now", GauntletRecorderPlugin.safeField("Light\tNode\nnow"));
		assertEquals("one two", GauntletRecorderPlugin.safeField("one\rtwo"));
	}
}

