package com.gauntletrecorder;

/**
 * Object / NPC / varp ids for The Gauntlet. Lifted from the all-in-one Gauntlet plugin
 * (github.com/kThisIsCvpv/gauntlet, BSD-2) - both Normal and Corrupted variants listed, since a
 * run is one or the other. The Hunllef itself is matched by name, not id, because its id (9035-9038)
 * cycles with its overhead prayer and we log that id as the boss's current style.
 */
final class GauntletIds
{
	private GauntletIds() {}

	static final int VARP_BOSS_ROOM = 9177;   // == 1 while inside the Hunllef arena
	static final int VARP_RAID_ROOM = 9178;   // == 1 anywhere inside the Gauntlet
	static final int VARP_HPBAR_HUD_INFO = 1682;   // boss HP HUD data varp (VarPlayerID.HPBAR_HUD_INFO); packing unverified - logged raw so offline analysis can decode it. Varbit 6099 (BOSS_HEALTH_CURRENT) read 0 all fight in CG - dead end

	static final int[] TORNADO_NPCS = {9025, 9039};

	// Floor-tile GroundObjects, one triplet per Gauntlet variant. A tile cycles base -> crimson
	// telegraph -> orange damage -> base through three consecutive ids. Corrupted 36046/47/48 (damage
	// from the Gauntlet Performance Tracker, github.com/powerus117/RLCGPerformanceTracker; crimson
	// confirmed from a recorded run to lead damage by 5-8 ticks). Regular 36149/50/51 (confirmed from a
	// recorded run: the 36149->36150->36151->36149 tile cycle). We log crimson + damage (the warning
	// and the hit) as FLOORTILE; the base id is the arena floor and is skipped (it covers every tile).
	static final int CRIMSON_TILE = 36047;       // corrupted telegraph
	static final int DAMAGE_TILE = 36048;        // corrupted damage
	static final int CRIMSON_TILE_REG = 36150;   // regular telegraph
	static final int DAMAGE_TILE_REG = 36151;    // regular damage

	static boolean isFloorTile(int id)
	{
		return id == CRIMSON_TILE || id == DAMAGE_TILE
			|| id == CRIMSON_TILE_REG || id == DAMAGE_TILE_REG;
	}

	static boolean isTornado(int npcId)
	{
		for (int t : TORNADO_NPCS)
		{
			if (t == npcId)
			{
				return true;
			}
		}
		return false;
	}

	/** Resource GameObject id -> short type label, or null if the object isn't a Gauntlet resource. */
	static String resourceType(int id)
	{
		// Regular-variant ids (35967-75) were mis-paired: the map read them scrambled so only phren
		// (35969) landed on the right type. Corrected against harvest positions across every recorded
		// run - both variants run sequentially ore/phren/fish/grym/linum. (Corrupted runs log the
		// 359xx ids in practice; the 360xx entries are kept for the regular Gauntlet.)
		switch (id)
		{
			case 36064: case 35967: return "ore";     // crystal deposit / mining
			case 36066: case 35969: return "phren";   // phren roots / woodcutting
			case 36068: case 35971: return "fish";    // fishing spot
			case 36070: case 35973: return "grym";    // grym roots / herblore
			case 36072: case 35975: return "linum";   // linum tirinum / farming
			default: return null;
		}
	}
}

