/**
 * Records the per-tick spatial state of a Corrupted Gauntlet run to disk - the companion to the
 * combat log, which has actions/damage but no positions.
 *
 * <p>Output: ~/.runelite/gauntlet-recorder/&lt;player&gt;/recorder-&lt;millis&gt;.txt - a fresh file per
 * login session (like the Combat Logger), append-only, tab-delimited, one event per line. Every line starts {@code <gameTick>\t<wallClockISO>\t<TYPE>} so it aligns with the
 * combat log (same tick counter) and stands alone by wall-clock. While inside the Gauntlet
 * (varp 9178) each game tick emits the player tile, the boss tile+id, and every tornado tile;
 * resources are logged once on spawn; every inventory change emits an INV delta line (the whole
 * gather/craft/cook/potion loop, since a Gauntlet inventory holds nothing else) and every worn-gear
 * change a WORN delta (catches equipped-gear upgrades INV can't see); game-object clicks and
 * non-player system messages are recorded as separate raw observations; the Hunllef/player dying emits
 * KILL/DEATH; NPC animation changes emit ANIM and each new projectile emits PROJ (attack style,
 * stomps and the prayer-disabling attack as observations rather than cadence inference); NPC
 * scene entry/exit emits NPC_SPAWN/NPC_DESPAWN plus an NPC_SEEN sweep at raid entry (when a
 * demi-boss becomes visible - preloaded vs revealed-at-door-open - is answered offline); every
 * hitsplat emits HIT, player animation changes emit PANIM, player HP/prayer changes emit STAT
 * (baseline at entry) and prayer toggles emit PRAYER delta tokens - the four streams that make a
 * run's damage, method and prayer analysis self-contained (no Combat Logger needed). Every position carries five coord columns
 * {@code tplX\ttplY\tplane\trawX\trawY}: template (un-instanced, shares the combat log's frame -
 * the working frame for fusion) and raw (real instanced position, unique per tile - node dedup key).
 *
 * <p>M3: floor tiles are GroundObjects (crimson telegraph / orange damage, both Gauntlet variants -
 * see {@link GauntletIds#isFloorTile}) - {@link #scanFloorTiles} logs every lit tile each
 * boss-room tick as {@code FLOORTILE} (full hazard-grid state).
 */
@Slf4j
@PluginDescriptor(
	name = "Gauntlet Recorder"
)
public class GauntletRecorderPlugin extends Plugin
{
	private static final Path OUT_DIR = Paths.get(RuneLite.RUNELITE_DIR.getAbsolutePath(), "gauntlet-recorder");

	@Inject
	private Client client;

	@Inject
	private GauntletRecorderConfig config;

	// The two player vitals whose exact track the fight analysis needs (HP for damage/eat effects,
	// prayer for drain/sip/zap effects) - other skills only move via xp, which STAT skips anyway.
	private static final Skill[] TRACKED_SKILLS = {Skill.HITPOINTS, Skill.PRAYER};

	private boolean inRaid = false;
	private boolean inBoss = false;
	private Path outFile;   // per-session file, created on first login (the name needs the player)
	private Map<Integer, Integer> inv = new HashMap<>();   // inventory baseline for delta logging, per raid
	private Map<Integer, Integer> worn = new HashMap<>();  // worn-equipment baseline (catches worn upgrades)
	private final Map<Skill, int[]> lastStat = new EnumMap<>(Skill.class);  // {boosted, base} baseline per tracked skill
	private Set<Prayer> activePrayers = EnumSet.noneOf(Prayer.class);       // prayer-delta baseline, per raid
	// projectiles already logged - weak refs, entries vanish when the client drops the projectile
	private final java.util.Set<Projectile> seenProjectiles =
		java.util.Collections.newSetFromMap(new java.util.WeakHashMap<>());

	@Override
	protected void startUp() throws Exception
	{
		inRaid = false;
		inBoss = false;
		outFile = null;
		log.info("Gauntlet Recorder started, log dir {}", OUT_DIR);
	}

	/**
	 * Start a fresh per-session log file under a per-character folder - the same pattern the Combat
	 * Logger uses ({@code <dir>/<player>/recorder-<millis>.txt}), so no single file grows unbounded
	 * and a session's recorder file lines up with its combat_log file. Called once, on first login.
	 */
	private void createLogFile()
	{
		Player me = client.getLocalPlayer();
		String name = me != null && me.getName() != null ? me.getName() : "unknown";
		String safe = name.replaceAll("[^A-Za-z0-9._-]", "_");
		outFile = OUT_DIR.resolve(safe).resolve("recorder-" + System.currentTimeMillis() + ".txt");
	}

	@Override
	protected void shutDown() throws Exception
	{
		write(line("SHUTDOWN", "plugin unloaded"));
	}

	// No GameStateChanged handler: LOGGED_IN fires after EVERY scene load (zone changes, teleports),
	// not just real logins, so a LOGIN line there is noise. File creation and the chat announce are
	// deferred to onGameTick anyway - at LOGGED_IN the player name is often still null and the chat
	// would land before the login messages.

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player me = client.getLocalPlayer();
		if (client.getGameState() != GameState.LOGGED_IN || me == null)
		{
			return;
		}
		if (outFile == null && me.getName() != null)  // now the name is loaded, open the session file
		{
			createLogFile();
			write(line("STARTUP", "plugin loaded"));
			if (config.chatConfirm())  // announce here (a beat after login) so it isn't the first line
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"<col=cc0000>Gauntlet Recorder is logging to .runelite/gauntlet-recorder</col>", null);
			}
		}

		boolean nowRaid = varp(GauntletIds.VARP_RAID_ROOM) == 1;
		boolean nowBoss = varp(GauntletIds.VARP_BOSS_ROOM) == 1;

		StringBuilder sb = new StringBuilder();
		if (nowRaid && !inRaid)
		{
			sb.append(line("GAUNTLET_ENTER", ""));
			inv = snapshot(client.getItemContainer(InventoryID.INV));    // inventory-delta baseline
			worn = snapshot(client.getItemContainer(InventoryID.WORN));  // worn-equipment baseline
			// STAT baseline at entry (the starting state the delta stream builds on); the prayer
			// baseline just clears - any prayer already lit logs as a :1 token on this first tick.
			lastStat.clear();
			activePrayers = EnumSet.noneOf(Prayer.class);
			for (Skill s : TRACKED_SKILLS)
			{
				int[] lv = {client.getBoostedSkillLevel(s), client.getRealSkillLevel(s)};
				lastStat.put(s, lv);
				sb.append(line("STAT", posActor(me.getWorldLocation())
					+ "\t" + s.name() + "\t" + lv[0] + "\t" + lv[1]));
			}
			// NPCs already in scene before the raid varp flipped - their NpcSpawned events fired
			// while the gate below still read 0, so sweep them once at entry (the entry board).
			for (NPC npc : client.getNpcs())
			{
				if (npc != null)
				{
					sb.append(line("NPC_SEEN", posActor(npc.getWorldLocation())
						+ "\t" + npc.getId() + "\t" + npc.getIndex()));
				}
			}
		}
		if (!nowRaid && inRaid)
		{
			sb.append(line("GAUNTLET_EXIT", ""));
		}
		if (nowBoss && !inBoss)
		{
			sb.append(line("BOSS_ROOM_ENTER", ""));
		}
		inRaid = nowRaid;
		inBoss = nowBoss;

		if (nowRaid)
		{
			sb.append(line("PLAYER", posActor(me.getWorldLocation())));
			scanPrayers(sb, me);
			for (NPC npc : client.getNpcs())
			{
				if (npc == null)
				{
					continue;
				}
				if (isBoss(npc))
				{
					// three raw candidate HP feeds, decoded offline: the HP-HUD varp (packing
					// unverified) and the overhead-bar ratio/scale. Varbit 6099 was 0 all fight in CG.
					sb.append(line("BOSS", posActor(npc.getWorldLocation()) + "\t" + npc.getId()
						+ "\t" + rawVarp(GauntletIds.VARP_HPBAR_HUD_INFO)
						+ "\t" + npc.getHealthRatio() + "\t" + npc.getHealthScale()));
				}
				else if (GauntletIds.isTornado(npc.getId()))
				{
					sb.append(line("TORNADO", posActor(npc.getWorldLocation()) + "\t" + npc.getId()));
				}
			}
			if (nowBoss)
			{
				scanFloorTiles(sb);
			}
		}

		if (sb.length() > 0)
		{
			write(sb.toString());
		}
	}

	/**
	 * Full per-tick telegraph grid: every tile on the player's plane carrying a crimson (36047) or
	 * orange/damaging (36048) floor GroundObject. One FLOORTILE line per tile, id included so the
	 * analysis can tell warning from damage - this is the reachability input (what is dangerous, and
	 * what is about to be, each tick). Scanning the whole plane is ~104^2 cheap field reads.
	 */
	private void scanFloorTiles(StringBuilder sb)
	{
		Scene scene = client.getScene();
		if (scene == null)
		{
			return;
		}
		Tile[][][] planes = scene.getTiles();
		int plane = client.getPlane();
		if (plane < 0 || plane >= planes.length)
		{
			return;
		}
		for (Tile[] col : planes[plane])
		{
			if (col == null)
			{
				continue;
			}
			for (Tile t : col)
			{
				if (t == null)
				{
					continue;
				}
				GroundObject g = t.getGroundObject();
				if (g != null && GauntletIds.isFloorTile(g.getId()))
				{
					sb.append(line("FLOORTILE", posActor(t.getWorldLocation()) + "\t" + g.getId()));
				}
			}
		}
	}

	/**
	 * Inventory + worn-equipment delta stream. You enter the Gauntlet empty, so the inventory holds
	 * nothing but Gauntlet items; every change is a gather, craft, cook, potion-make or consumption
	 * (logged as {@code INV}). The worn container ({@code WORN}) is logged the same way - it catches
	 * gear/weapon upgrades done while equipped, which the inventory never sees (a T1->T2 armour upgrade
	 * on worn gear is invisible to INV). Each line carries the player's tile and an {@code id:delta}
	 * token per changed item (+ gained / - spent). No interpretation here - a craft is a resource down
	 * and a product up in the same event; the offline analysis reads that.
	 */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!inRaid)
		{
			return;
		}
		if (event.getContainerId() == InventoryID.INV)
		{
			inv = writeDelta("INV", inv, snapshot(event.getItemContainer()));
		}
		else if (event.getContainerId() == InventoryID.WORN)
		{
			worn = writeDelta("WORN", worn, snapshot(event.getItemContainer()));
		}
	}

	/** Diff a container snapshot against its baseline, log the nonzero deltas, return the new baseline. */
	private Map<Integer, Integer> writeDelta(String type, Map<Integer, Integer> old, Map<Integer, Integer> now)
	{
		StringBuilder tokens = new StringBuilder();
		java.util.Set<Integer> ids = new java.util.HashSet<>(now.keySet());
		ids.addAll(old.keySet());
		for (int id : ids)
		{
			int delta = now.getOrDefault(id, 0) - old.getOrDefault(id, 0);
			if (delta != 0)
			{
				tokens.append("\t").append(id).append(":").append(delta);
			}
		}
		if (tokens.length() > 0)
		{
			Player me = client.getLocalPlayer();
			write(line(type, posActor(me == null ? null : me.getWorldLocation()) + tokens));
		}
		return now;
	}

	/**
	 * Prayer-delta stream, scanned per tick against the client's live prayer state. One PRAYER line
	 * per tick that anything toggled, {@code NAME:1}/{@code NAME:0} token per change (the INV-delta
	 * shape). Tick resolution is the native resolution of prayer flicking, so nothing is lost by not
	 * hooking varbits directly - and the enum names stay stable where raw varbit ids don't. Overheads
	 * feed wrong-pray/chip attribution; Deadeye/Mystic Vigour feed the offense-uptime read; the zap's
	 * prayer wipe shows up as a burst of :0 tokens on one tick.
	 */
	private void scanPrayers(StringBuilder sb, Player me)
	{
		StringBuilder tokens = new StringBuilder();
		for (Prayer p : Prayer.values())
		{
			boolean now;
			try
			{
				now = client.isPrayerActive(p);
			}
			catch (RuntimeException ignored)
			{
				continue;
			}
			if (now != activePrayers.contains(p))
			{
				tokens.append("\t").append(p.name()).append(":").append(now ? 1 : 0);
				if (now)
				{
					activePrayers.add(p);
				}
				else
				{
					activePrayers.remove(p);
				}
			}
		}
		if (tokens.length() > 0)
		{
			sb.append(line("PRAYER", posActor(me.getWorldLocation()) + tokens));
		}
	}

	/**
	 * Hitsplat stream - every damage/heal splat on any actor in the raid, no interpretation. This is
	 * the damage record the analysis previously needed the Combat Logger for: splats on NPCs = damage
	 * dealt (accuracy, dealt totals, prep kill counting), splats on the player = damage taken (chip
	 * vs over-cap, env-hit attribution joins these to the TORNADO/FLOORTILE contact streams). NPC id
	 * and index are blank when the actor is the player (the PROJ convention); the mine flag is the
	 * client's own attribution of who dealt the splat.
	 */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!inRaid)
		{
			return;
		}
		Actor a = event.getActor();
		String npcId = a instanceof NPC ? String.valueOf(((NPC) a).getId()) : "";
		String npcIndex = a instanceof NPC ? String.valueOf(((NPC) a).getIndex()) : "";
		Hitsplat h = event.getHitsplat();
		write(line("HIT", posActor(a.getWorldLocation())
			+ "\t" + npcId + "\t" + npcIndex
			+ "\t" + h.getHitsplatType() + "\t" + h.getAmount() + "\t" + (h.isMine() ? 1 : 0)));
	}

	/**
	 * Player vitals stream - boosted/base HP and Prayer on change, plus a baseline at raid entry.
	 * StatChanged also fires on pure xp gain, so identical levels are skipped; what remains is the
	 * exact HP/prayer track (eat/sip effects, drain, the zap's prayer hit) that the fight analysis
	 * previously reconstructed from the Combat Logger's stat rows.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!inRaid)
		{
			return;
		}
		Skill s = event.getSkill();
		if (s != Skill.HITPOINTS && s != Skill.PRAYER)
		{
			return;
		}
		int[] now = {event.getBoostedLevel(), event.getLevel()};
		int[] old = lastStat.get(s);
		if (old != null && old[0] == now[0] && old[1] == now[1])
		{
			return;   // xp-only change, levels unmoved
		}
		lastStat.put(s, now);
		Player me = client.getLocalPlayer();
		write(line("STAT", posActor(me == null ? null : me.getWorldLocation())
			+ "\t" + s.name() + "\t" + now[0] + "\t" + now[1]));
	}

	/**
	 * Animation streams - a raw observation per change, no interpretation. NPC changes emit ANIM: the
	 * Hunllef's attack (8419), stomp (8420) and style-switch (8754 to-mage / 8755 to-range) animations
	 * are the ground truth for attack style and stomp timing, which offline analysis otherwise has to
	 * infer from hitsplat cadence; demi-boss and other NPC animations come along for free. The local
	 * player's changes emit PANIM - attack animations are what the method/wasted-attack analysis reads
	 * (bow/staff/halberd are distinct ids), and were the last stream still requiring the Combat Logger.
	 * Idle resets (-1) are skipped on both.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!inRaid)
		{
			return;
		}
		Actor a = event.getActor();
		if (a == client.getLocalPlayer() && a != null)
		{
			int anim = a.getAnimation();
			if (anim >= 0)
			{
				write(line("PANIM", posActor(a.getWorldLocation()) + "\t" + anim));
			}
			return;
		}
		if (!(a instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) a;
		int anim = npc.getAnimation();
		if (anim >= 0)
		{
			write(line("ANIM", posActor(npc.getWorldLocation())
				+ "\t" + npc.getId() + "\t" + npc.getIndex() + "\t" + anim));
		}
	}

	/**
	 * NPC visibility stream - raw spawn/despawn observations, no interpretation. Whether a
	 * demi-boss enters the scene at raid entry (preloaded) or only when its corridor is opened is
	 * exactly the open question this stream answers; offline analysis joins each spawn to the
	 * room-reveal timeline and only credits what was legitimately visible at each moment. Gated on
	 * the live raid varp (like RESOURCE) so scene-load spawns during the entry transition are kept;
	 * anything that entered the scene before the varp flipped is covered by the NPC_SEEN entry
	 * sweep in onGameTick. Nothing here is surfaced in-game - append-only disk log, no overlay.
	 */
	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (varp(GauntletIds.VARP_RAID_ROOM) != 1)
		{
			return;
		}
		NPC npc = event.getNpc();
		write(line("NPC_SPAWN", posActor(npc.getWorldLocation())
			+ "\t" + npc.getId() + "\t" + npc.getIndex()));
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (varp(GauntletIds.VARP_RAID_ROOM) != 1)
		{
			return;
		}
		NPC npc = event.getNpc();
		write(line("NPC_DESPAWN", posActor(npc.getWorldLocation())
			+ "\t" + npc.getId() + "\t" + npc.getIndex()));
	}

	/**
	 * Projectile stream - one line per projectile at first sighting (ProjectileMoved fires every
	 * tick a projectile is alive; the weak set dedups without touching cycle arithmetic). The
	 * Hunllef's magic, ranged and prayer-disabling attacks are distinct projectile ids, so attack
	 * style becomes an observation instead of a cadence fit. Carries the target tile, the firing
	 * NPC's id (blank if not an NPC) and whether it targets the player.
	 */
	@Subscribe
	public void onProjectileMoved(ProjectileMoved event)
	{
		if (!inRaid)
		{
			return;
		}
		Projectile p = event.getProjectile();
		if (!seenProjectiles.add(p))
		{
			return;
		}
		Actor src = p.getSourceActor();
		String srcId = src instanceof NPC ? String.valueOf(((NPC) src).getId()) : "";
		String atMe = p.getTargetActor() == client.getLocalPlayer() && client.getLocalPlayer() != null ? "1" : "0";
		write(line("PROJ", posActor(p.getTargetPoint()) + "\t" + p.getId() + "\t" + srcId + "\t" + atMe));
	}

	/** Self-mark the outcome: the Hunllef dying = KILL, the player dying = DEATH (no combat-log needed). */
	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!inRaid)
		{
			return;
		}
		Actor a = event.getActor();
		if (a == client.getLocalPlayer())
		{
			write(line("DEATH", posActor(a.getWorldLocation())));
		}
		else if (a instanceof NPC && isBoss((NPC) a))
		{
			write(line("KILL", posActor(a.getWorldLocation())));
		}
	}

	/** Full inventory as id -> quantity (stacks summed). */
	private static Map<Integer, Integer> snapshot(ItemContainer c)
	{
		Map<Integer, Integer> m = new HashMap<>();
		if (c != null)
		{
			for (Item it : c.getItems())
			{
				if (it.getId() >= 0)
				{
					m.merge(it.getId(), it.getQuantity(), Integer::sum);
				}
			}
		}
		return m;
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (varp(GauntletIds.VARP_RAID_ROOM) != 1)
		{
			return;
		}
		GameObject go = event.getGameObject();
		String type = GauntletIds.resourceType(go.getId());
		if (type != null)
		{
			write(line("RESOURCE", posActor(go.getWorldLocation()) + "\t" + go.getId() + "\t" + type));
		}
	}

	/**
	 * Raw game-object interactions inside the Gauntlet. The clicked object's scene tile resolves to
	 * both template and raw-instance coordinates, so an offline consumer can identify which wall node
	 * was clicked even when several rooms reuse the same template. No success is inferred here: a
	 * matching system message or subsequent scene change remains a separate observation.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		if (varp(GauntletIds.VARP_RAID_ROOM) != 1 || !isGameObjectAction(entry.getType()))
		{
			return;
		}
		WorldView worldView = client.getWorldView(entry.getWorldViewId());
		if (worldView == null)
		{
			worldView = client.getTopLevelWorldView();
		}
		WorldPoint target = WorldPoint.fromScene(worldView, entry.getParam0(), entry.getParam1(), worldView.getPlane());
		write(line("OBJECT_CLICK", posActor(target)
			+ "\t" + entry.getIdentifier()
			+ "\t" + entry.getType().name()
			+ "\t" + safeField(entry.getOption())
			+ "\t" + safeField(entry.getTarget())));
	}

	/**
	 * Non-player chat generated by the game while inside the Gauntlet. GAMEMESSAGE and SPAM cover the
	 * two channels used by Gauntlet action feedback; public, private, friends and clan chat are never
	 * written. Message text stays otherwise raw so offline analysis can discover new signals.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (varp(GauntletIds.VARP_RAID_ROOM) != 1 || !isRecordedMessageType(event.getType()))
		{
			return;
		}
		write(line("GAME_MESSAGE", event.getType().name() + "\t" + safeField(event.getMessage())));
	}

	static boolean isRecordedMessageType(ChatMessageType type)
	{
		return type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM;
	}

	@SuppressWarnings("deprecation")
	static boolean isGameObjectAction(MenuAction action)
	{
		return action == MenuAction.ITEM_USE_ON_GAME_OBJECT
			|| action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT
			|| action == MenuAction.GAME_OBJECT_FIRST_OPTION
			|| action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION
			|| action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	/** Replace field separators and line breaks without changing any other message content. */
	static String safeField(String value)
	{
		return value == null ? "" : value.replace('\t', ' ').replace('\r', ' ').replace('\n', ' ');
	}

	private int varp(int id)
	{
		try
		{
			return client.getVarbitValue(client.getVarps(), id);
		}
		catch (RuntimeException ignored)
		{
			return 0;
		}
	}

	private int rawVarp(int id)
	{
		try
		{
			return client.getVarpValue(id);
		}
		catch (RuntimeException ignored)
		{
			return -1;
		}
	}

	private static boolean isBoss(NPC npc)
	{
		String name = npc.getName();
		return name != null && name.matches("(Crystalline|Corrupted) Hunllef");
	}

	/**
	 * Five coord columns: {@code tplX\ttplY\tplane\trawX\trawY}. Both roles are settled (2026-07-09):
	 *
	 * <p><b>Template</b> (tpl*) un-instances via {@code fromLocalInstance} - the SAME transform the
	 * combat logger uses, so those columns share its coordinate frame (verified delta (0,0)). It is
	 * the working frame for all downstream fusion: arena hazard layers, gather/node markers, env-hit
	 * contact attribution. Template space reuses one room stamp across many instance rooms, so a
	 * coord alone can't say which 7x7 room it's in - the parser resolves room identity from the
	 * solved route instead.
	 *
	 * <p><b>Raw</b> (raw*) is the actor's real position in the instanced region - unique per physical
	 * tile. It did NOT pan out as a direct room-placement shortcut (the combat-log world solve stayed);
	 * it's the resource-dedup key, and that is load-bearing: measured across 16 recorded runs, 6 had
	 * two physically distinct nodes collide on one template tile (rooms sharing a stamp) - tpl-only
	 * dedup would merge those. Also the collapse-free ground truth for forensic cross-checks.
	 */
	private String posActor(WorldPoint worldLoc)
	{
		if (worldLoc == null)
		{
			return "\t\t\t\t";
		}
		LocalPoint lp = LocalPoint.fromWorld(client, worldLoc);
		return fmt(lp == null ? null : WorldPoint.fromLocalInstance(client, lp), worldLoc);
	}

	private static String fmt(WorldPoint tpl, WorldPoint raw)
	{
		String t = tpl == null ? "\t\t" : tpl.getX() + "\t" + tpl.getY() + "\t" + tpl.getPlane();
		String r = raw == null ? "\t" : raw.getX() + "\t" + raw.getY();
		return t + "\t" + r;
	}

	/** One tab-delimited line: gameTick, local wall-clock ISO (offset), TYPE, then the given body.
	 * Local (not UTC) so it lines up with the Combat Logger's local timestamps for the tick join. */
	private String line(String type, String body)
	{
		int tick = client.getGameState() == GameState.LOGGED_IN ? client.getTickCount() : -1;
		String row = tick + "\t" + OffsetDateTime.now() + "\t" + type;
		if (body != null && !body.isEmpty())
		{
			row += "\t" + body;
		}
		return row + System.lineSeparator();
	}

	/** Append a block (one or more complete lines). Best-effort: never throw into the client. */
	private void write(String block)
	{
		if (outFile == null)
		{
			return;   // nothing to log before the first login creates the session file
		}
		try
		{
			Files.createDirectories(outFile.getParent());
			Files.write(outFile, block.getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.CREATE, StandardOpenOption.APPEND);
		}
		catch (IOException e)
		{
			log.warn("Gauntlet Recorder could not write to {}", outFile, e);
		}
	}

	@Provides
	GauntletRecorderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GauntletRecorderConfig.class);
	}
